HEX = "0123456789abcdefABCDEF"

def is_ipv4(addr):
    parts = addr.split(".")
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit() or int(p) > 255:
            return False
    return True

def is_mac(addr):
    parts = addr.replace("-", ":").split(":")
    if len(parts) != 6:
        return False
    for p in parts:
        if len(p) != 2:
            return False
        for ch in p:
            if ch not in HEX:
                return False
    return True

def what_is(addr):
    if is_ipv4(addr):
        return "IPv4"
    if is_mac(addr):
        return "MAC"
    return "not valid"

for a in ["192.168.1.24", "00:1A:2B:3C:4D:5E", "10.0.256.7", "A4-5E-60-F1-02-9C"]:
    print(a, "->", what_is(a))

